class Solution:
    def mergeCloseCharacters(self, s, k):
        lst = list(s)
        while True:
            done = True
            for i in range(len(lst)):
                for j in range(i + 1, min(len(lst), i + k + 1)):
                    if lst[j] == lst[i]:
                        del lst[j]
                        done = False
                        break
                if not done:
                    break
            if done:
                return ''.join(lst)

