class Solution {
public:
    string mergeCloseCharacters(string s, int k) {
        bool changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i < (int)s.size() && !changed; i++)
                for (int j = i + 1; j <= min<int>(s.size() - 1, i + k); j++)
                    if (s[j] == s[i]) { s.erase(s.begin() + j); changed = true; break; }
        }
        return s;
    }
};

