class Solution:
    def mergeCloseCharacters(self, s, k):
        n = len(s)
        tree = [0] * (n + 1)
        def upd(i, v):
            i += 1
            while i <= n:
                tree[i] += v
                i += i & -i
        def qry(i):
            i += 1
            r = 0
            while i > 0:
                r += tree[i]
                i -= i & -i
            return r
        for i in range(n):
            upd(i, 1)
        prev = {}
        alive = [True] * n
        for i, c in enumerate(s):
            if c in prev and qry(i) - qry(prev[c]) <= k:
                alive[i] = False
                upd(i, -1)
            else:
                prev[c] = i
        return ''.join(c for i, c in enumerate(s) if alive[i])

