class Solution {
    public String mergeCloseCharacters(String s, int k) {
        int n = s.length();
        int[] tree = new int[n + 1];
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j <= n; j += j & -j) tree[j]++;
        int[] prev = new int[26];
        java.util.Arrays.fill(prev, -1);
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            int rank = 0;
            for (int j = i + 1; j > 0; j -= j & -j) rank += tree[j];
            if (prev[c] != -1) {
                int pr = 0;
                for (int j = prev[c] + 1; j > 0; j -= j & -j) pr += tree[j];
                if (rank - pr <= k) {
                    for (int j = i + 1; j <= n; j += j & -j) tree[j]--;
                    continue;
                }
            }
            prev[c] = i;
            res.append(s.charAt(i));
        }
        return res.toString();
    }
}

